import{_ as t,o as a,c as o,a2 as i}from"./chunks/framework.Crpw6aS5.js";const m=JSON.parse('{"title":"EchoFlow Code: an AI coding tool that lands in real development workflows","description":"","frontmatter":{"layout":"home","hero":{"name":"EchoFlow Code","text":"A local coding agent for real projects","tagline":"Work from the terminal, desktop, or IM channels with Qingyun API (EchoFlowAPI), official Claude, Anthropic-compatible models, multi-agent workflows, memory, Skills, and Computer Use.","actions":[{"theme":"brand","text":"Quick Start","link":"/en/guide/quick-start"},{"theme":"brand","text":"Configure Qingyun API","link":"https://api.echoflow.cn/"},{"theme":"alt","text":"Download Latest","link":"https://github.com/LiuGuangHS/EchoFlow-ClaudeCode/releases/latest"},{"theme":"alt","text":"Qingyun AI Apps","link":"https://ai.echoflow.cn/"}]},"features":[{"icon":{"src":"/images/home/terminal-desktop.svg","alt":"CLI and desktop","width":32,"height":32,"wrap":false},"title":"CLI and desktop together","details":"Use the terminal for fast work and the desktop app for sessions, projects, and settings.","link":"/desktop/"},{"icon":{"src":"/images/home/provider.svg","alt":"Provider","width":32,"height":32,"wrap":false},"title":"Controlled model routing","details":"Start with Qingyun API, then add Anthropic / OpenAI-compatible gateways or local models.","link":"/en/guide/third-party-models"},{"icon":{"src":"/images/home/agents.svg","alt":"Multi-agent","width":32,"height":32,"wrap":false},"title":"Multi-agent work","details":"Split research, implementation, review, and verification with Teams and Worktrees.","link":"/en/agent/"},{"icon":{"src":"/images/home/memory-skills.svg","alt":"Memory and Skills","width":32,"height":32,"wrap":false},"title":"Memory and Skills","details":"Keep project preferences, team rules, and reusable workflows across sessions.","link":"/en/memory/"},{"icon":{"src":"/images/home/mobile-im.svg","alt":"Mobile and IM","width":32,"height":32,"wrap":false},"title":"Mobile and IM access","details":"Scan into H5 on Android, or start local tasks from Telegram, Feishu, WeChat, and DingTalk.","link":"/en/mobile/"},{"icon":{"src":"/images/home/computer-use.svg","alt":"Computer Use","width":32,"height":32,"wrap":false},"title":"Computer Use","details":"Control screenshots, mouse, keyboard, and app windows through the local Python Bridge.","link":"/en/features/computer-use"}]},"headers":[],"relativePath":"en/index.md","filePath":"en/index.md","lastUpdated":1783619669000}'),r={name:"en/index.md"};function n(s,e,l,d,c,h){return a(),o("div",null,[...e[0]||(e[0]=[i(`<h1 id="echoflow-code-an-ai-coding-tool-that-lands-in-real-development-workflows" tabindex="-1">EchoFlow Code: an AI coding tool that lands in real development workflows <a class="header-anchor" href="#echoflow-code-an-ai-coding-tool-that-lands-in-real-development-workflows" aria-label="Permalink to &quot;EchoFlow Code: an AI coding tool that lands in real development workflows&quot;">​</a></h1><p>EchoFlow Code is a locally runnable coding agent product with a CLI, desktop app, local server, IM adapters, and documented quality gates. It is built for developers and teams who want AI coding to operate inside real repositories, real branches, and real verification loops.</p><h2 id="recommended-qingyun-api" tabindex="-1">Recommended: Qingyun API <a class="header-anchor" href="#recommended-qingyun-api" aria-label="Permalink to &quot;Recommended: Qingyun API&quot;">​</a></h2><p>New users should start with <strong>Qingyun (EchoFlow) API</strong> at <a href="https://api.echoflow.cn" target="_blank" rel="noreferrer">api.echoflow.cn</a>, also shown as EchoFlowAPI in the product. The desktop Providers page includes a Qingyun API quick-connect card where you can register an account, generate a system access token, choose main / haiku models, and set it as the default Provider.</p><p>Qingyun API is the recommended model entry for EchoFlow Code: it matches the desktop Provider flow, keeps model configuration simple, and still leaves room to use official Claude, Anthropic-compatible APIs, OpenAI-compatible gateways, or local models later. Teams with their own model gateway can start with Qingyun API as the first validation path, then switch to Custom Provider when needed.</p><h2 id="echoflow-ecosystem" tabindex="-1">EchoFlow Ecosystem <a class="header-anchor" href="#echoflow-ecosystem" aria-label="Permalink to &quot;EchoFlow Ecosystem&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Destination</th><th>URL</th><th>What to use it for</th></tr></thead><tbody><tr><td>Qingyun API main site</td><td><a href="https://api.echoflow.cn" target="_blank" rel="noreferrer">api.echoflow.cn</a></td><td>Register, create a system access token, and configure the recommended EchoFlow Code Provider.</td></tr><tr><td>Qingyun AI online apps</td><td><a href="https://ai.echoflow.cn" target="_blank" rel="noreferrer">ai.echoflow.cn</a></td><td>Try Qingyun AI applications online for lightweight AI workflows.</td></tr><tr><td>EchoFlow Code docs</td><td><a href="https://code.echoflow.cn" target="_blank" rel="noreferrer">code.echoflow.cn</a></td><td>Download the desktop app, read setup guides, connect models, and learn multi-agent workflows.</td></tr></tbody></table><p>If you want to try online AI applications immediately, start at <a href="https://ai.echoflow.cn" target="_blank" rel="noreferrer">ai.echoflow.cn</a>. If you want AI to work inside a local codebase, download EchoFlow Code and connect it with Qingyun API from <a href="https://api.echoflow.cn" target="_blank" rel="noreferrer">api.echoflow.cn</a>.</p><h2 id="who-it-is-for" tabindex="-1">Who it is for <a class="header-anchor" href="#who-it-is-for" aria-label="Permalink to &quot;Who it is for&quot;">​</a></h2><ul><li>Developers who prefer terminal workflows but want a stronger desktop experience.</li><li>Teams that need one coding agent surface for Claude, EchoFlowAPI, OpenAI-compatible gateways, or local models.</li><li>Projects that benefit from multi-agent exploration, implementation, review, testing, and release work.</li><li>Users who want to start tasks, monitor progress, and continue sessions from Telegram, Feishu, WeChat, or DingTalk.</li><li>Teams evaluating Computer Use, desktop automation, real UI validation, and local permission boundaries.</li></ul><h2 id="what-you-can-do" tabindex="-1">What you can do <a class="header-anchor" href="#what-you-can-do" aria-label="Permalink to &quot;What you can do&quot;">​</a></h2><h3 id="complete-coding-tasks-inside-local-repositories" tabindex="-1">Complete coding tasks inside local repositories <a class="header-anchor" href="#complete-coding-tasks-inside-local-repositories" aria-label="Permalink to &quot;Complete coding tasks inside local repositories&quot;">​</a></h3><p>EchoFlow Code can inspect real code, edit files, run tests, check impact, and leave a maintainable handoff. The CLI is fast for daily development, while the desktop app is better for multi-session, multi-project, and visual workflows.</p><h3 id="split-complex-work-across-agents" tabindex="-1">Split complex work across agents <a class="header-anchor" href="#split-complex-work-across-agents" aria-label="Permalink to &quot;Split complex work across agents&quot;">​</a></h3><p>The multi-agent system helps separate research, implementation, testing, and review. Worktree isolation keeps parallel exploration from colliding with your main working tree.</p><h3 id="preserve-project-knowledge" tabindex="-1">Preserve project knowledge <a class="header-anchor" href="#preserve-project-knowledge" aria-label="Permalink to &quot;Preserve project knowledge&quot;">​</a></h3><p>Memory turns project preferences, team constraints, and decisions into reusable context. Skills package repeated workflows into capabilities that can be reused across tasks.</p><h3 id="continue-from-desktop-mobile-and-im-channels" tabindex="-1">Continue from desktop, mobile, and IM channels <a class="header-anchor" href="#continue-from-desktop-mobile-and-im-channels" aria-label="Permalink to &quot;Continue from desktop, mobile, and IM channels&quot;">​</a></h3><p>The desktop app exposes sessions, settings, Providers, IM configuration, and Computer Use. The Android client scans desktop H5 launch links and keeps chat, approvals, file inputs, and WebSocket flows inside a mobile WebView; IM adapters let you send tasks to local EchoFlow Code from chat tools.</p><h2 id="quick-start" tabindex="-1">Quick Start <a class="header-anchor" href="#quick-start" aria-label="Permalink to &quot;Quick Start&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span></span></code></pre></div><p>Desktop users can go straight to <a href="https://github.com/LiuGuangHS/EchoFlow-ClaudeCode/releases/latest" target="_blank" rel="noreferrer">GitHub Releases for the latest build</a>, or read <a href="/desktop/04-installation">Installation &amp; Build</a> first. For model setup, start with Qingyun API in the <a href="/desktop/01-quick-start">Desktop Quick Start</a>, then use <a href="/en/guide/third-party-models">Third-Party Models</a> when you want additional Providers.</p><h2 id="download-guide" tabindex="-1">Download Guide <a class="header-anchor" href="#download-guide" aria-label="Permalink to &quot;Download Guide&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Your device</th><th>Recommended download</th><th>Best fit</th></tr></thead><tbody><tr><td>Windows x64</td><td><code>EchoFlow-Code-&lt;version&gt;-win-x64.exe</code></td><td>Daily desktop use, multi-project sessions, and visual Provider setup.</td></tr><tr><td>macOS Apple Silicon</td><td><code>EchoFlow-Code-&lt;version&gt;-mac-arm64.dmg</code></td><td>M-series Mac users who want the desktop app and local Computer Use.</td></tr><tr><td>macOS Intel</td><td><code>EchoFlow-Code-&lt;version&gt;-mac-x64.dmg</code></td><td>Intel Mac users; first launch may require a manual security approval.</td></tr><tr><td>Linux x64</td><td><code>.AppImage</code> or <code>.deb</code></td><td>AppImage for quick trials, deb for a fixed workstation setup.</td></tr><tr><td>Linux ARM64</td><td><code>linux-arm64.AppImage</code> or <code>linux-arm64.deb</code></td><td>ARM64 Linux devices and development machines.</td></tr><tr><td>Android</td><td>Mobile APK or local build</td><td>Connect to desktop with an H5 Token over a trusted LAN or your own HTTPS entry.</td></tr></tbody></table><p>If you are not sure what to choose, start with the desktop app. If you already live in the terminal, use the CLI. If a packaged build is not convenient, run the Web UI and connect it to the local server from your browser.</p><h2 id="architecture-recommendations" tabindex="-1">Architecture Recommendations <a class="header-anchor" href="#architecture-recommendations" aria-label="Permalink to &quot;Architecture Recommendations&quot;">​</a></h2><table tabindex="0"><thead><tr><th>User type</th><th>Recommended architecture</th><th>Why it fits</th></tr></thead><tbody><tr><td>Individual developer</td><td>Desktop app + Qingyun API / EchoFlowAPI Provider</td><td>Lowest setup cost for projects, sessions, and model configuration.</td></tr><tr><td>Terminal-heavy developer</td><td>CLI + local repository + project-level config</td><td>Keeps shell, git, tests, and editor workflows in the center.</td></tr><tr><td>Small engineering team</td><td>Desktop app + multi-agent workflows + memory + Skills</td><td>Turns team constraints, repeated workflows, and review standards into reusable process.</td></tr><tr><td>Multi-model or private-model user</td><td>Local server + Anthropic/OpenAI-compatible Provider + Ollama or gateway</td><td>Gives one routing layer for cloud models, local models, and proxy gateways.</td></tr><tr><td>Mobile remote user</td><td>Desktop app + Android client / IM adapters + H5 Token + local server</td><td>Scan into H5 or start tasks from IM while the local machine performs real code operations.</td></tr><tr><td>UI automation and validation user</td><td>Desktop app + Computer Use + project test commands</td><td>Lets the agent see and operate the desktop while tests verify real interface behavior.</td></tr></tbody></table><p>You can adopt these pieces gradually: start with the desktop app, connect a Provider, and open multi-agent, memory, Skills, IM, or Computer Use only when the workflow actually needs them.</p><h2 id="documentation" tabindex="-1">Documentation <a class="header-anchor" href="#documentation" aria-label="Permalink to &quot;Documentation&quot;">​</a></h2><ul><li><a href="/en/guide/quick-start">Quick Start</a>: installation, startup, and basic usage.</li><li><a href="/desktop/">Desktop</a>: Electron client, Providers, IM, Computer Use, and build notes.</li><li><a href="/en/mobile/">Mobile</a>: Android client, QR connection, H5 Token, and trusted-network notes.</li><li><a href="/en/agent/">Multi-Agent System</a>: agent calls, Teams, parallel tasks, and implementation details.</li><li><a href="/en/memory/">Memory System</a>: extraction, retrieval, AutoDream, and local storage.</li><li><a href="/en/skills/01-usage-guide">Skills System</a>: custom capabilities, activation, and execution constraints.</li><li><a href="/en/channel/">Channel System</a>: IM channel architecture and adapter concepts.</li><li><a href="/en/features/computer-use">Computer Use</a>: local desktop control and safety boundaries.</li></ul>`,30)])])}const u=t(r,[["render",n]]);export{m as __pageData,u as default};
